for relative, (expected_sha256, encoded) in FILES.items():
    body = zlib.decompress(base64.b85decode(encoded.encode("ascii")))
    observed = hashlib.sha256(body).hexdigest()
    if observed != expected_sha256:
        raise SystemExit(f"payload digest mismatch: {relative}: expected={expected_sha256} observed={observed}")
    path = ROOT / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(body)
    print(f"wrote {relative}: sha256={observed}")
